#!/usr/bin/env node
// Builds the static site into ./public from the engine's own data, so every
// page, table and calendar feed is generated by the code that does the counting.
//   node scripts/build.js           build
//   node scripts/build.js --check   fail if ./public is out of date (CI)

import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';
import * as E from '../src/engine/index.js';
import { toICS } from '../src/engine/ics.js';
import { TOOLS } from '../src/worker/mcp.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SITE = JSON.parse(readFileSync(join(ROOT, 'site/site.json'), 'utf8'));
const CHECK = process.argv.includes('--check');
const OUT = CHECK ? mkdtempSync(join(tmpdir(), 'duly-')) : join(ROOT, 'public');
const ORIGIN = SITE.origin;
const YEAR = +E.RULES_VERIFIED.slice(0, 4);

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pages = []; // for the sitemap

function write(path, content) {
  const file = join(OUT, path);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
}

function page(path, html, { index = true } = {}) {
  write(path.endsWith('/') ? `${path}index.html` : path, html);
  if (index) pages.push(path);
}

// ---------------------------------------------------------------------------
// Layout
// ---------------------------------------------------------------------------

const NAV = [
  ['/#calculators', 'Calculators'],
  ['/holidays/', 'Holidays'],
  ['/developers/', 'API & AI'],
  ['/pricing/', 'Pricing'],
];

function layout({ path, title, description, body, schema = [], bodyClass = '', noindex = false, ogTitle }) {
  const url = ORIGIN + path;
  const nav = NAV.map(([href, label]) => `<a href="${href}"${path !== '/' && href.startsWith(path) && path.length > 1 ? ' aria-current="page"' : ''}>${label}</a>`).join('');
  return `<!doctype html>
<html lang="en-NZ">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
<meta name="description" content="${esc(description)}">
${noindex ? '<meta name="robots" content="noindex">' : `<link rel="canonical" href="${url}">`}
<meta property="og:type" content="website">
<meta property="og:site_name" content="Duly">
<meta property="og:title" content="${esc(ogTitle || title)}">
<meta property="og:description" content="${esc(description)}">
<meta property="og:url" content="${url}">
<meta property="og:image" content="${ORIGIN}/assets/og.png">
<meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#f4f2ec" media="(prefers-color-scheme: light)">
<meta name="theme-color" content="#0f1110" media="(prefers-color-scheme: dark)">
<link rel="icon" href="/favicon.svg" type="image/svg+xml">
<link rel="preload" href="/assets/fonts/switzer-variable.woff2" as="font" type="font/woff2" crossorigin>
<link rel="stylesheet" href="/assets/duly.css">
<link rel="modulepreload" href="/assets/engine/index.js">
${schema.map((s) => `<script type="application/ld+json">${JSON.stringify(s)}</script>`).join('\n')}
</head>
<body${bodyClass ? ` class="${bodyClass}"` : ''}>
<a class="sr-only" href="#main">Skip to content</a>
<header class="bar"><div class="wrap"><a class="brand" href="/" aria-label="Duly home">Duly<span class="brand-dot">.</span></a><nav class="nav" aria-label="Main">${nav}</nav></div></header>
<main id="main">
${body}
</main>
<footer class="site"><div class="wrap">
<div class="cols">
<div><a class="brand" href="/">Duly<span class="brand-dot">.</span></a><p class="small" style="margin-top:8px">${esc(SITE.tagline)}</p></div>
<nav aria-label="Footer"><a href="/#calculators">Calculators</a><a href="/holidays/">Public holidays</a><a href="/developers/">API &amp; MCP</a><a href="/pricing/">Pricing</a><a href="/about/">Sources &amp; accuracy</a><a href="/terms/">Terms</a><a href="/privacy/">Privacy</a><a href="mailto:${SITE.contact}">Contact</a></nav>
</div>
<p class="fine">Duly applies the statutory definitions it cites and shows its working. It isn’t legal advice: check the timeframe provisions that apply to you, including contract terms, court directions and service rules. Rules last checked ${esc(E.formatLong(E.RULES_VERIFIED).replace(/^\w+ /, ''))}. Made in Aotearoa by <a href="${SITE.makerUrl}">${esc(SITE.maker)}</a>.</p>
</div></footer>
<script type="module" src="/assets/app.js"></script>
</body>
</html>
`;
}

// ---------------------------------------------------------------------------
// Calculator form (server-rendered so it works and indexes before JS runs)
// ---------------------------------------------------------------------------

const FAMILIES = [
  ['information', 'Official information'],
  ['property', 'Property and tenancy'],
  ['planning', 'Planning and building'],
  ['construction', 'Construction'],
  ['courts', 'Courts'],
  ['business', 'Companies, tax and contracts'],
  ['general', 'General'],
];

function regimeOptions(selected) {
  return FAMILIES.map(([fam, label]) => {
    const list = E.REGIMES.filter((r) => r.family === fam);
    if (!list.length) return '';
    return `<optgroup label="${esc(label)}">${list.map((r) => `<option value="${r.id}"${r.id === selected ? ' selected' : ''}>${esc(r.menuLabel || r.short)}</option>`).join('')}</optgroup>`;
  }).join('');
}

function provinceOptions() {
  return '<option value="">Choose a province…</option>'
    + E.PROVINCES.map((p) => `<option value="${p.id}">${esc(p.name)} (${esc(p.areas)})</option>`).join('');
}

function calcForm(regimeId, { embed = false, pinned = false } = {}) {
  const r = E.getRegime(regimeId);
  return `<form class="calc" id="calc" data-calc data-regime="${r.id}"${embed ? ' data-embed="true"' : ''}${pinned ? ' data-pinned="true"' : ''} novalidate>
<div class="calc-form">
<label>Counting under<select name="regime">${regimeOptions(r.id)}</select></label>
<p class="rule-line" data-rule-line>${esc(r.summaryLine)}</p>
<div class="presets" data-presets aria-label="Common timeframes"></div>
<div class="calc-row">
<label><span data-from-label>Start date</span><input type="date" name="from" required></label>
<label><span data-days-label>Working days</span><input type="number" name="days" min="0" max="2000" step="1" inputmode="numeric" value="${r.presets?.[0]?.days ?? 20}" required></label>
</div>
<div class="calc-row three">
<div role="group" aria-label="Direction" class="dir" data-dir-wrap><button type="button" data-dir="after" aria-pressed="true">After</button><button type="button" data-dir="before" aria-pressed="false">Before</button></div>
<label data-province-wrap${r.rules.anniversary === 'location' ? '' : ' hidden'}>Province (anniversary day)<select name="province">${provinceOptions()}</select></label>
</div>
<label data-service-wrap hidden>How the notice was given<select name="service"></select></label>
<details class="adv"><summary>More options</summary><div class="stack">
<label>Count in<select name="unit"><option value="working">Working days</option><option value="calendar">Calendar days</option></select></label>
<label data-roll-wrap hidden>If the answer isn’t a working day<select name="roll"><option value="none">Leave it</option><option value="next">Move to the next working day</option><option value="previous">Move to the previous working day</option></select></label>
<label class="check"><input type="checkbox" name="on"> Count the start date itself as day 1</label>
</div></details>
<noscript><p class="note">The calculator needs JavaScript. The <a href="/developers/">API</a> works without it.</p></noscript>
</div>
<div class="result" data-result aria-live="polite"></div>
${embed ? `<p class="credit">Counted by <a href="${ORIGIN}/" target="_blank" rel="noopener">Duly</a> · <a href="${ORIGIN}/${r.slug}/" target="_blank" rel="noopener">How ${esc(r.short)} counts working days</a></p>` : ''}
</form>`;
}

// ---------------------------------------------------------------------------
// Shared bits
// ---------------------------------------------------------------------------

const fmtDay = (iso) => E.formatLong(iso);
const fmtShort = (iso) => E.formatShort(iso);

function summerWindow(r, year) {
  const b = r.rules.blackout;
  if (!b) return null;
  const from = `${year}-${b.from}`;
  const to = `${b.to < b.from ? year + 1 : year}-${b.to}`;
  return { from, to };
}

function definitionBlock(r) {
  const d = r.definition || {};
  const text = d.quote
    ? `<blockquote>${esc(d.quote)}<cite>${esc(r.citation)}${d.status === 'paraphrase' ? ' (paraphrased)' : ''}</cite></blockquote>`
    : '';
  const list = E.describeRulesList(r).map((x) => `<li>${esc(x)}</li>`).join('');
  return `${text}<p>Under ${esc(r.the)}, a day is <strong>not</strong> a working day if it is:</p><ul>${list}</ul>`;
}

function presetTable(r) {
  if (!r.presets || !r.presets.length) return '';
  return `<div class="table-wrap"><table><thead><tr><th>Timeframe</th><th>Period</th><th>Counted from</th><th>Provision</th></tr></thead><tbody>
${r.presets.map((p) => `<tr><td>${esc(p.label)}${p.note ? `<span class="tagline">${esc(p.note)}</span>` : ''}</td><td class="date">${p.days} ${p.unit === 'calendar' ? 'calendar' : 'working'} days${p.direction === 'before' ? ' before' : ''}</td><td>${esc(p.trigger || '')}</td><td>${esc(p.cite || '')}</td></tr>`).join('\n')}
</tbody></table></div>`;
}

function faqBlock(faq) {
  return `<div class="faq">${faq.map(({ q, a }) => `<details><summary>${esc(q)}</summary><p>${a}</p></details>`).join('')}</div>`;
}

function faqSchema(faq) {
  return {
    '@context': 'https://schema.org', '@type': 'FAQPage',
    mainEntity: faq.map(({ q, a }) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a.replace(/<[^>]+>/g, '') } })),
  };
}

function crumbs(items) {
  const html = `<p class="crumbs">${items.map(([href, label], i) => (i < items.length - 1 ? `<a href="${href}">${esc(label)}</a> / ` : esc(label))).join('')}</p>`;
  const schema = {
    '@context': 'https://schema.org', '@type': 'BreadcrumbList',
    itemListElement: items.map(([href, label], i) => ({ '@type': 'ListItem', position: i + 1, name: label, item: ORIGIN + href })),
  };
  return { html, schema };
}

const APP_SCHEMA = {
  '@context': 'https://schema.org', '@type': 'WebApplication', name: 'Duly', url: `${ORIGIN}/`,
  applicationCategory: 'BusinessApplication', operatingSystem: 'Any', inLanguage: 'en-NZ',
  description: SITE.description,
  offers: { '@type': 'Offer', price: '0', priceCurrency: 'NZD' },
  creator: { '@type': 'Organization', name: SITE.maker, url: SITE.makerUrl },
};

// The same start date, counted under every regime: the clearest way to show
// why one calculator for "working days" is not enough.
function comparison(from, days) {
  const rows = E.REGIMES.filter((r) => r.compare !== false).map((r) => {
    const province = r.rules.anniversary === 'location' ? 'auckland' : undefined;
    const out = E.addWorkingDays({ regime: r.id, from, days, province, trace: false });
    return { r, out, province };
  }).sort((a, b) => (a.out.result < b.out.result ? -1 : a.out.result > b.out.result ? 1 : a.r.short.localeCompare(b.r.short)));
  const earliest = rows[0].out.result;
  const latest = rows[rows.length - 1].out.result;
  const spread = E.diffDays(earliest, latest);
  return { rows, earliest, latest, spread };
}

