function calendars() {
  const years = [YEAR - 1, YEAR, YEAR + 1, YEAR + 2, YEAR + 3];
  const national = years.flatMap((y) => E.nationalHolidays(y)).filter((h) => !E.isWeekend(h.date) || !E.nationalHolidays(+h.date.slice(0, 4)).some((o) => o.key === h.key && o.mondayised))
    .map((h) => ({ uid: `${h.date}-${h.key}`, date: h.date, summary: h.name + (h.mondayised ? ' (observed)' : ''), description: `New Zealand public holiday. ${ORIGIN}/holidays/${h.date.slice(0, 4)}/` }));
  const domain = ORIGIN.replace(/^https?:\/\//, '');
  write('calendars/nz-public-holidays.ics', toICS({ name: 'NZ public holidays', description: `New Zealand national public holidays from Duly (${domain})`, events: national, stamp: E.RULES_VERIFIED, domain, refreshDays: 7 }));
  for (const p of E.PROVINCES) {
    const anniv = years.map((y) => E.anniversaryDay(p.id, y)).map((a) => ({ uid: `${a.date}-${p.id}`, date: a.date, summary: a.name, description: `${a.rule}. ${ORIGIN}/holidays/${a.date.slice(0, 4)}/` }));
    write(`calendars/nz-public-holidays-${p.id}.ics`, toICS({
      name: `NZ public holidays + ${p.name} Anniversary`, description: `New Zealand public holidays and ${p.name} Anniversary Day from Duly (${domain})`,
      events: [...national, ...anniv].sort((a, b) => (a.date < b.date ? -1 : 1)), stamp: E.RULES_VERIFIED, domain, refreshDays: 7,
    }));
  }
}

