function build() {
  if (!CHECK) rmSync(OUT, { recursive: true, force: true });
  mkdirSync(OUT, { recursive: true });
  cpSync(join(ROOT, 'site/static'), OUT, { recursive: true });
  cpSync(join(ROOT, 'src/engine'), join(OUT, 'assets/engine'), { recursive: true });
  home();
  for (const r of E.REGIMES.filter((x) => x.page)) regimePage(r);
  holidaysIndex();
  for (const y of SITE.holidayYears) holidayYear(y);
  developers();
  pricing();
  about();
  legal();
  embedPage();
  notFound();
  calendars();
  machineFiles();
}

function listFiles(dir, base = dir) {
  return readdirSync(dir).flatMap((f) => {
    const p = join(dir, f);
    return statSync(p).isDirectory() ? listFiles(p, base) : [relative(base, p)];
  }).sort();
}

build();
if (CHECK) {
  const committed = join(ROOT, 'public');
  const a = existsSync(committed) ? listFiles(committed) : [];
  const b = listFiles(OUT);
  const diffs = [];
  for (const f of new Set([...a, ...b])) {
    if (!a.includes(f) || !b.includes(f)) { diffs.push(f); continue; }
    if (!readFileSync(join(committed, f)).equals(readFileSync(join(OUT, f)))) diffs.push(f);
  }
  rmSync(OUT, { recursive: true, force: true });
  if (diffs.length) {
    console.error(`public/ is out of date (${diffs.length} files differ), e.g.\n  ${diffs.slice(0, 10).join('\n  ')}\nRun: npm run build`);
    process.exit(1);
  }
  console.log(`public/ is up to date (${b.length} files).`);
} else {
  console.log(`Built ${pages.length} pages into public/.`);
}
